mapper.select:
SELECT * FROM audit_record 
WHERE business_id = #{businessId} 
AND audit_type = #{auditType} 
AND is_deleted = 0
ORDER BY create_time DESC
LIMIT 1

SELECT * FROM audit_record
WHERE is_deleted = 0

    AND audit_type = #{auditType}


    AND current_status = #{currentStatus}


    AND current_admin_id = #{currentAdminId}

ORDER BY 
    CASE priority WHEN 3 THEN 0 WHEN 2 THEN 1 WHEN 1 THEN 2 ELSE 3 END,
    create_time DESC

SELECT * FROM audit_record WHERE applicant_id = #{applicantId} AND is_deleted = 0
AND audit_type = #{auditType}
ORDER BY create_time DESC

SELECT ar.id, ar.audit_no AS auditNo, ar.audit_type AS auditType, ar.business_id AS businessId, ar.title, ar.content, ar.current_status AS currentStatus, ar.priority, ar.applicant_id AS applicantId, ar.submit_time AS submitTime, ar.finish_time AS finishTime, ar.current_admin_id AS currentAdminId, u.name AS applicantName, u.avatar AS applicantAvatar, a.name AS currentAdminName FROM audit_record ar LEFT JOIN user_info u ON ar.applicant_id = u.id LEFT JOIN admin_info a ON ar.current_admin_id = a.id WHERE ar.is_deleted = 0
AND ar.audit_type = #{query.auditType}
AND ar.current_status = #{query.status}
AND ar.priority = #{query.priority}
AND ( ar.audit_no LIKE CONCAT('%', #{query.keyword}, '%') OR ar.title LIKE CONCAT('%', #{query.keyword}, '%') )
AND ar.submit_time >= #{query.startTime}
AND ar.submit_time <= #{query.endTime}
ORDER BY ar.priority DESC, ar.current_status ASC, ar.submit_time DESC
